css:
.sl-course-list.sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-course-list .sl-row-surface { background-color: var(--smartlearn-bg); }
.sl-course-list .sl-text-primary { color: var(--smartlearn-primary); }
.sl-course-list .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-course-list .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-course-list .sl-bg-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border); }
.sl-course-list .sl-border { border-color: var(--smartlearn-card-border); }
.sl-course-list .sl-card-radius { border-radius: var(--smartlearn-radius, 1rem); }
.sl-course-list h2, .sl-course-list h3 { font-family: var(--smartlearn-heading-font, inherit); }
.sl-course-list .sl-tracking-wide { letter-spacing: 0.1em; }
.sl-course-list .sl-icon-box {
    background-color: var(--smartlearn-bg);
    background-color: color-mix(in oklab, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
}
.sl-course-list .sl-list-row {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.sl-course-list .sl-action-cell { display: flex; justify-content: flex-start; }
.sl-course-list .sl-action-btn {
    background-color: transparent;
    color: var(--smartlearn-text);
    border: 1px solid var(--smartlearn-card-border);
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.sl-course-list .sl-action-btn:hover,
.sl-course-list .sl-action-btn:focus-visible {
    background-color: var(--smartlearn-btn-bg);
    border-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-course-list .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
@media (min-width: 992px) {
    .sl-course-list { padding-top: 6rem !important; padding-bottom: 6rem !important; }
    .sl-course-list .sl-list-grid {
        display: grid;
        grid-template-columns: minmax(0, 1.5fr) 1fr 0.75fr 0.75fr auto;
        align-items: center;
        gap: 1.5rem;
    }
    .sl-course-list .sl-action-cell { justify-content: flex-end; }
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-course-list .sl-list-row:hover {
        transform: translateX(5px);
        box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.06);
        border-color: var(--smartlearn-primary);
    }
    [dir="rtl"] .sl-course-list .sl-list-row:hover { transform: translateX(-5px); }
}
@media (prefers-reduced-motion: reduce) {
    .sl-course-list .sl-list-row, .sl-course-list .sl-action-btn { transition: none; }
}
